<!doctype html><html lang="en"><meta charset="utf-8"><title>Manage items</title><main><h1>Items</h1><p><a href="<?= site_url('admin') ?>">Dashboard</a> · <a href="<?= site_url('admin/write') ?>">Write a post</a></p><?php foreach ($items as $item): ?><article><h2><?= esc($item['item_title']) ?></h2><p><?= esc($item['item_status']) ?> · <?= esc($item['feed_domain'] ?? 'This site') ?></p><form method="post" action="<?= site_url('admin/items/' . $item['ID'] . '/status') ?>"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $item['item_status'] === 'draft' ? 'publish' : 'draft' ?>"><button><?= $item['item_status'] === 'draft' ? 'Publish' : 'Unpublish' ?></button></form><form method="post" action="<?= site_url('admin/items/' . $item['ID'] . '/delete') ?>"><?= csrf_field() ?><button>Delete</button></form></article><?php endforeach; ?></main></html>
